CREATE TABLE `agenda_bloqueos` (
  `id` int NOT NULL AUTO_INCREMENT,
  `medico_id` int NOT NULL,
  `fecha_inicio` date NOT NULL,
  `fecha_fin` date NOT NULL,
  `tipo` enum('bloqueo','liberacion') COLLATE utf8mb4_unicode_ci NOT NULL,
  `motivo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `agenda_bloqueos_medico_fechas_idx` (`medico_id`,`fecha_inicio`,`fecha_fin`),
  CONSTRAINT `agenda_bloqueos_ibfk_1` FOREIGN KEY (`medico_id`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `agenda_bloqueos` (`id`, `medico_id`, `fecha_inicio`, `fecha_fin`, `tipo`, `motivo`, `createdAt`, `updatedAt`) VALUES (2,16,'2026-06-01','2026-06-07','bloqueo',NULL,'2026-05-16 18:08:02','2026-05-16 18:08:02'),(5,16,'2026-06-01','2026-06-30','liberacion',NULL,'2026-05-16 19:41:23','2026-05-16 19:41:23'),(6,16,'2026-06-01','2026-06-30','bloqueo',NULL,'2026-05-16 19:41:40','2026-05-16 19:41:40');
CREATE TABLE `atenciones_medicas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `cita_id` int NOT NULL,
  `paciente_id` int NOT NULL,
  `medico_id` int NOT NULL,
  `presion_sistolica` int DEFAULT NULL,
  `presion_diastolica` int DEFAULT NULL,
  `frecuencia_cardiaca` int DEFAULT NULL,
  `temperatura` decimal(4,1) DEFAULT NULL,
  `peso` decimal(5,2) DEFAULT NULL,
  `talla` decimal(5,2) DEFAULT NULL,
  `saturacion_oxigeno` int DEFAULT NULL,
  `motivo_consulta` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `anamnesis` text COLLATE utf8mb4_unicode_ci,
  `examen_fisico` text COLLATE utf8mb4_unicode_ci,
  `diagnostico` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `cie10` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `plan_tratamiento` text COLLATE utf8mb4_unicode_ci,
  `indicaciones` text COLLATE utf8mb4_unicode_ci,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `atenciones_cita_uq` (`cita_id`),
  KEY `atenciones_paciente_idx` (`paciente_id`),
  KEY `atenciones_medico_idx` (`medico_id`),
  CONSTRAINT `atenciones_medicas_ibfk_217` FOREIGN KEY (`cita_id`) REFERENCES `citas` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `atenciones_medicas_ibfk_218` FOREIGN KEY (`paciente_id`) REFERENCES `pacientes` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `atenciones_medicas_ibfk_219` FOREIGN KEY (`medico_id`) REFERENCES `usuarios` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `atenciones_medicas` (`id`, `cita_id`, `paciente_id`, `medico_id`, `presion_sistolica`, `presion_diastolica`, `frecuencia_cardiaca`, `temperatura`, `peso`, `talla`, `saturacion_oxigeno`, `motivo_consulta`, `anamnesis`, `examen_fisico`, `diagnostico`, `cie10`, `plan_tratamiento`, `indicaciones`, `createdAt`, `updatedAt`) VALUES (1,1,1,16,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'No indica Motivo','Paciente que sufre de cirrosis hepatica medicamentosa hacer 3 años , asistiendo a parasistesis regularmente cada 2 a 3 semanas','inchason abdomen, ademas presenta infeccion cutanea en estomago','enfermedad terminal',NULL,'lactulosa para deposiciones, diureticos regularmente','lacutolosa 2 veces al dia 40ml','2026-05-14 14:58:36','2026-05-14 14:58:36'),(2,2,1,18,NULL,NULL,NULL,NULL,22.00,45.00,NULL,'control de presion','paciente con alta de presion','se encuentra picadura de insecto','antiinflamatorios por 3 dias',NULL,'antiinflamatorios por 3 dias','reposo mucha agua y descanso','2026-05-14 17:25:20','2026-05-14 17:25:20'),(3,227,47,16,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'Control cardíaco','fuertes dolores de pecho','ningun allasgo fisico','pre infarto',NULL,'lozartan','reposo , dia','2026-05-18 15:42:19','2026-05-18 15:42:19');
CREATE TABLE `citas` (
  `id` int NOT NULL AUTO_INCREMENT,
  `paciente_id` int NOT NULL,
  `medico_id` int NOT NULL,
  `secretaria_id` int DEFAULT NULL,
  `fecha_hora` datetime NOT NULL,
  `duracion_min` int DEFAULT '30',
  `motivo` text COLLATE utf8mb4_unicode_ci,
  `estado` enum('programada','confirmada','cancelada','completada') COLLATE utf8mb4_unicode_ci DEFAULT 'programada',
  `notas` text COLLATE utf8mb4_unicode_ci,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  KEY `citas_medico_fecha_idx` (`medico_id`,`fecha_hora`),
  KEY `citas_paciente_idx` (`paciente_id`),
  KEY `secretaria_id` (`secretaria_id`),
  CONSTRAINT `citas_ibfk_304` FOREIGN KEY (`paciente_id`) REFERENCES `pacientes` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `citas_ibfk_305` FOREIGN KEY (`medico_id`) REFERENCES `usuarios` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `citas_ibfk_306` FOREIGN KEY (`secretaria_id`) REFERENCES `usuarios` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=333 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
