CREATE TABLE `medico_previsiones` (
  `medico_id` int NOT NULL,
  `prevision_id` int NOT NULL,
  PRIMARY KEY (`medico_id`,`prevision_id`),
  UNIQUE KEY `medico_previsiones_prevision_id_medico_id_unique` (`medico_id`,`prevision_id`),
  KEY `prevision_id` (`prevision_id`),
  CONSTRAINT `medico_previsiones_ibfk_1` FOREIGN KEY (`medico_id`) REFERENCES `medicos_perfil` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `medico_previsiones_ibfk_2` FOREIGN KEY (`prevision_id`) REFERENCES `previsiones` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
