CREATE TABLE `medico_subespecialidades` (
  `medico_id` int NOT NULL,
  `subespecialidad_id` int NOT NULL,
  PRIMARY KEY (`medico_id`,`subespecialidad_id`),
  UNIQUE KEY `medico_subespecialidades_subespecialidad_id_medico_id_unique` (`medico_id`,`subespecialidad_id`),
  KEY `subespecialidad_id` (`subespecialidad_id`),
  CONSTRAINT `medico_subespecialidades_ibfk_1` FOREIGN KEY (`medico_id`) REFERENCES `medicos_perfil` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `medico_subespecialidades_ibfk_2` FOREIGN KEY (`subespecialidad_id`) REFERENCES `subespecialidades` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
