CREATE TABLE `medicos_perfil` (
  `id` int NOT NULL AUTO_INCREMENT,
  `usuario_id` int NOT NULL,
  `descripcion` text COLLATE utf8mb4_unicode_ci,
  `acepta_isapre` tinyint(1) DEFAULT '0',
  `acepta_fonasa` tinyint(1) DEFAULT '0',
  `acepta_particular` tinyint(1) DEFAULT '0',
  `valor_particular` int DEFAULT NULL,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  `modalidad_presencial` tinyint(1) DEFAULT '0',
  `modalidad_telemedicina` tinyint(1) DEFAULT '0',
  `numero_registro` varchar(30) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `fecha_registro_prestador` date DEFAULT NULL,
  `titulo_profesional` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `entidad_certificadora` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `vigencia_especialidad` date DEFAULT NULL,
  `especialidad_id` int DEFAULT NULL,
  `direccion_consulta` varchar(200) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `telefono_consulta` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `medicos_perfil_usuario_uq` (`usuario_id`),
  UNIQUE KEY `medicos_perfil_registro_uq` (`numero_registro`),
  KEY `especialidad_id` (`especialidad_id`),
  CONSTRAINT `medicos_perfil_ibfk_326` FOREIGN KEY (`usuario_id`) REFERENCES `usuarios` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `medicos_perfil_ibfk_327` FOREIGN KEY (`especialidad_id`) REFERENCES `especialidades` (`id`) ON DELETE SET NULL ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
