CREATE TABLE `receta_items` (
  `id` int NOT NULL AUTO_INCREMENT,
  `receta_id` int NOT NULL,
  `medicamento` varchar(200) COLLATE utf8mb4_unicode_ci NOT NULL,
  `dosis` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `frecuencia` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `duracion` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `indicaciones` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  KEY `receta_items_receta_idx` (`receta_id`),
  CONSTRAINT `receta_items_ibfk_1` FOREIGN KEY (`receta_id`) REFERENCES `recetas` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO `receta_items` (`id`, `receta_id`, `medicamento`, `dosis`, `frecuencia`, `duracion`, `indicaciones`) VALUES (1,1,'CARBOCISTEÍNA CÁPSULAS 375 mg',NULL,'c/8 horas','7 dias','no fumar y alchol');
CREATE TABLE `recetas` (
