  `atencion_id` int NOT NULL,
  `paciente_id` int NOT NULL,
  `medico_id` int NOT NULL,
  `observaciones` text COLLATE utf8mb4_unicode_ci,
  `createdAt` datetime NOT NULL,
  `updatedAt` datetime NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `atencion_id` (`atencion_id`),
  UNIQUE KEY `recetas_atencion_uq` (`atencion_id`),
  KEY `recetas_paciente_idx` (`paciente_id`),
  KEY `recetas_medico_idx` (`medico_id`),
  CONSTRAINT `recetas_ibfk_118` FOREIGN KEY (`atencion_id`) REFERENCES `atenciones_medicas` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `recetas_ibfk_119` FOREIGN KEY (`paciente_id`) REFERENCES `pacientes` (`id`) ON UPDATE CASCADE,
  CONSTRAINT `recetas_ibfk_120` FOREIGN KEY (`medico_id`) REFERENCES `usuarios` (`id`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
